import type { Toolset } from '../registry.ts'
import { loadApiSchema } from './schema.ts'
import { registerSchemaTools } from './tools.ts'

// A toolset that generates its tools from the database, rather than declaring
// them. On each request it reads the description PostgREST serves at the REST
// root and registers read and write tools for every table, updatable view, and
// function the calling user is allowed to see.
//
// Nothing here is generated at build time, so a new table becomes a new set of
// tools as soon as the schema cache expires — no redeploy.

export const postgrestToolset: Toolset = {
  name: 'postgrest',
  description: 'Database tools generated from the PostgREST schema.',
  async register(server, { supabase, accessToken }) {
    const schema = await loadApiSchema(accessToken)
    registerSchemaTools(server, supabase, schema)
  },
}

import { getDefaultPublishableKey, getSupabaseEnvironment } from '../../supabase.ts'

// Reads the API description PostgREST serves at the REST root and turns it into
// a small model this toolset can generate tools from.
//
// PostgREST emits Swagger 2.0, where non-body parameters carry `type` directly
// rather than a `schema`. Generic OpenAPI-to-MCP converters read
// `parameter.schema`, so they either drop every filter or need a 2.0-to-3.0
// conversion step first. Reading it directly is both smaller and more faithful:
// PostgREST's shape is regular, and the parts worth exposing as tools (tables,
// updatable views, functions) are all identifiable from it.
//
// The description is filtered by the requesting role's privileges, so the tools
// a user sees already reflect what they are allowed to reach.

export type ColumnType = 'string' | 'number' | 'integer' | 'boolean' | 'object' | 'array' | 'json'

export type Column = {
  name: string
  type: ColumnType
  /** The Postgres type, e.g. `uuid` or `timestamp with time zone`. */
  format: string | null
  description: string | null
  isPrimaryKey: boolean
  /** Required by the table and without a default, so an insert must supply it. */
  isRequiredOnInsert: boolean
}

export type Resource = {
  /** The name to address in PostgREST, unchanged. */
  name: string
  description: string | null
  columns: Column[]
  primaryKey: string[]
  /** Which verbs PostgREST exposes, which is how a read-only view is identified. */
  canSelect: boolean
  canInsert: boolean
  canUpdate: boolean
  canDelete: boolean
}

export type RpcFunction = {
  name: string
  description: string | null
  args: Column[]
  /** PostgREST exposes immutable and stable functions on GET; volatile ones only on POST. */
  isReadOnly: boolean
}

export type ApiSchema = {
  resources: Resource[]
  functions: RpcFunction[]
}

type JsonObject = Record<string, unknown>

const isObject = (value: unknown): value is JsonObject =>
  typeof value === 'object' && value !== null && !Array.isArray(value)

/** Resolve a local `#/...` JSON pointer, which is all PostgREST uses. */
function resolveRef(spec: JsonObject, node: unknown): unknown {
  if (!isObject(node)) return node
  const ref = node.$ref
  if (typeof ref !== 'string' || !ref.startsWith('#/')) return node

  let current: unknown = spec
  for (const rawSegment of ref.slice(2).split('/')) {
    const segment = rawSegment.replaceAll('~1', '/').replaceAll('~0', '~')
    if (!isObject(current)) return undefined
    current = current[segment]
  }
  return current
}

function columnType(property: JsonObject): ColumnType {
  const format = typeof property.format === 'string' ? property.format : ''
  // jsonb columns arrive with a format and no type, and accept any JSON value.
  if (format === 'json' || format === 'jsonb') return 'json'
  if (format.endsWith('[]')) return 'array'

  switch (property.type) {
    case 'integer':
      return 'integer'
    case 'number':
      return 'number'
    case 'boolean':
      return 'boolean'
    case 'object':
      return 'object'
    case 'array':
      return 'array'
    case 'string':
      return 'string'
    default:
      return 'json'
  }
}

/**
 * PostgREST embeds key information in descriptions as pseudo-tags, e.g.
 * `Note:\nThis is a Primary Key.<pk/>` and
 * `<fk table='authors' column='id'/>`. Keep the human sentence, turn the
 * foreign-key tag into something a model can act on, and drop the markup.
 */
function readDescription(raw: unknown): { text: string | null; isPrimaryKey: boolean } {
  if (typeof raw !== 'string' || !raw) return { text: null, isPrimaryKey: false }

  const isPrimaryKey = raw.includes('<pk/>')
  const foreignKey = raw.match(/<fk table='([^']+)' column='([^']+)'\/>/)

  let text = raw
    .replace(/<pk\/>/g, '')
    .replace(/<fk table='[^']*' column='[^']*'\/>/g, '')
    .replace(/^Note:\s*/m, '')
    .replace(/\s+/g, ' ')
    .trim()

  if (foreignKey) {
    text = [text, `References ${foreignKey[1]}.${foreignKey[2]}.`].filter(Boolean).join(' ')
  }

  return { text: text || null, isPrimaryKey }
}

function parseColumns(definition: unknown): Column[] {
  if (!isObject(definition) || !isObject(definition.properties)) return []

  const required = Array.isArray(definition.required)
    ? definition.required.filter((name): name is string => typeof name === 'string')
    : []

  return Object.entries(definition.properties).map(([name, rawProperty]) => {
    const property = isObject(rawProperty) ? rawProperty : {}
    const { text, isPrimaryKey } = readDescription(property.description)

    return {
      name,
      type: columnType(property),
      format: typeof property.format === 'string' ? property.format : null,
      description: text,
      isPrimaryKey,
      // A column with a default (a generated id, a timestamp) is required by the
      // table but must not be required of the caller.
      isRequiredOnInsert: required.includes(name) && property.default === undefined,
    }
  })
}

/** The body parameter's schema for a POST path, resolving a `$ref` if present. */
function bodySchema(spec: JsonObject, operation: unknown): unknown {
  if (!isObject(operation) || !Array.isArray(operation.parameters)) return undefined

  for (const rawParameter of operation.parameters) {
    const parameter = resolveRef(spec, rawParameter)
    if (isObject(parameter) && parameter.in === 'body') {
      return resolveRef(spec, parameter.schema)
    }
  }
  return undefined
}

export function parseApiSchema(rawSpec: unknown): ApiSchema {
  if (!isObject(rawSpec) || !isObject(rawSpec.paths)) {
    throw new Error('The PostgREST description is missing its paths.')
  }

  const definitions = isObject(rawSpec.definitions) ? rawSpec.definitions : {}
  const resources: Resource[] = []
  const functions: RpcFunction[] = []

  for (const [path, rawOperations] of Object.entries(rawSpec.paths)) {
    // `/` is the description itself.
    if (path === '/' || !isObject(rawOperations)) continue

    if (path.startsWith('/rpc/')) {
      const name = path.slice('/rpc/'.length)
      const operation = rawOperations.post ?? rawOperations.get
      if (!isObject(operation)) continue

      functions.push({
        name,
        description: readDescription(operation.description ?? operation.summary).text,
        args: parseColumns(bodySchema(rawSpec, rawOperations.post)),
        isReadOnly: 'get' in rawOperations,
      })
      continue
    }

    const name = path.slice(1)
    const definition = definitions[name]
    const columns = parseColumns(definition)
    if (!columns.length) continue

    resources.push({
      name,
      description: isObject(definition) ? readDescription(definition.description).text : null,
      columns,
      primaryKey: columns.filter((column) => column.isPrimaryKey).map((column) => column.name),
      canSelect: 'get' in rawOperations,
      canInsert: 'post' in rawOperations,
      canUpdate: 'patch' in rawOperations,
      canDelete: 'delete' in rawOperations,
    })
  }

  return { resources, functions }
}

// -----------------------------------------------------------------------------
// Fetching, with a per-worker cache
// -----------------------------------------------------------------------------

type CacheEntry = { schema: ApiSchema; fetchedAt: number }

let cache: CacheEntry | null = null

function cacheTtlMs(): number {
  const configured = Number(Deno.env.get('MCP_POSTGREST_SCHEMA_TTL')?.trim())
  const seconds = Number.isFinite(configured) && configured >= 0 ? configured : 300
  return seconds * 1000
}

function postgrestConnection(): { restUrl: string; apiKey: string } {
  const environment = getSupabaseEnvironment()

  return {
    restUrl: `${environment.url.replace(/\/+$/, '')}/rest/v1/`,
    apiKey: getDefaultPublishableKey(),
  }
}

/**
 * The API schema as the calling user sees it. Cached per worker: it describes
 * shape, not rows, and it is the same for every user of a given role — Row Level
 * Security is still applied to each individual tool call.
 */
export async function loadApiSchema(accessToken: string): Promise<ApiSchema> {
  const ttl = cacheTtlMs()
  if (cache && ttl > 0 && Date.now() - cache.fetchedAt < ttl) {
    return cache.schema
  }

  const { restUrl, apiKey } = postgrestConnection()
  const response = await fetch(restUrl, {
    headers: {
      apikey: apiKey,
      Authorization: `Bearer ${accessToken}`,
      Accept: 'application/json',
    },
  })

  if (!response.ok) {
    throw new Error(
      `Unable to read the PostgREST schema (${response.status}). Check that the REST API is reachable.`
    )
  }

  const schema = parseApiSchema(await response.json())
  cache = { schema, fetchedAt: Date.now() }
  return schema
}

/** Drop the cached schema. Exposed for tests and for a schema-change hook. */
export function clearSchemaCache(): void {
  cache = null
}

import type { McpServer } from 'npm:@modelcontextprotocol/sdk@1.29.0/server/mcp'
import type { SupabaseClient } from 'npm:@supabase/supabase-js@2.108.2'
import { z } from 'npm:zod@4.4.3'

import { jsonResult, runtimeErrorResult } from '../result.ts'
import type { ApiSchema, Column, Resource, RpcFunction } from './schema.ts'

// Turns the parsed API schema into MCP tools.
//
// The tools are intent-named (`list_todos`, not `GetTodos`) and take structured
// filters rather than raw PostgREST query syntax, because a model that has to
// guess `id=eq.<uuid>` from a bare string parameter gets it wrong. An operator
// enum gives it a menu instead, and this file does the translation.

/** Operators worth exposing. PostgREST supports more; these cover ordinary use. */
const FILTER_OPERATORS = [
  'eq',
  'neq',
  'gt',
  'gte',
  'lt',
  'lte',
  'like',
  'ilike',
  'in',
  'is',
  'cs',
  'cd',
] as const

const OPERATOR_GUIDE =
  'eq/neq: equal, not equal. gt/gte/lt/lte: ordering comparisons. ' +
  'like/ilike: pattern match, case-sensitive and insensitive, with * as the wildcard. ' +
  'in: comma-separated list of values. is: null, true, or false. ' +
  'cs/cd: contains, contained by, for array and json columns.'

const MAX_ROWS = 1000
const DEFAULT_ROWS = 50

type Filter = {
  column: string
  operator: (typeof FILTER_OPERATORS)[number]
  value: string
}

// -----------------------------------------------------------------------------
// Schema construction
// -----------------------------------------------------------------------------

/** MCP tool names allow letters, digits, underscore, and hyphen. */
function toolName(action: string, resource: string): string {
  const safe = resource.replace(/[^a-zA-Z0-9_-]/g, '_')
  return `${action}_${safe}`.slice(0, 128)
}

function columnNames(columns: Column[]): [string, ...string[]] {
  const names = columns.map((column) => column.name)
  return names as [string, ...string[]]
}

/** A one-line summary of the columns, so a model can plan without a second call. */
function columnSummary(columns: Column[]): string {
  return columns
    .map((column) => {
      const notes = [column.format, column.isPrimaryKey ? 'primary key' : null]
        .filter(Boolean)
        .join(', ')
      return notes ? `${column.name} (${notes})` : column.name
    })
    .join('; ')
}

function valueSchema(column: Column): z.ZodTypeAny {
  const description = [column.format ? `${column.format}.` : null, column.description]
    .filter(Boolean)
    .join(' ')

  const base = (() => {
    switch (column.type) {
      case 'integer':
        return z.number().int()
      case 'number':
        return z.number()
      case 'boolean':
        return z.boolean()
      case 'array':
        return z.array(z.unknown())
      case 'object':
      case 'json':
        // jsonb takes any JSON value, including scalars and arrays.
        return z.unknown()
      default:
        return z.string()
    }
  })()

  return description ? base.describe(description) : base
}

/** Row shape for an insert: only columns without a default are required. */
function insertShape(columns: Column[]): z.ZodRawShape {
  return Object.fromEntries(
    columns.map((column) => [
      column.name,
      column.isRequiredOnInsert ? valueSchema(column) : valueSchema(column).nullable().optional(),
    ])
  )
}

/** Row shape for an update: every column optional, and nullable to clear it. */
function updateShape(columns: Column[]): z.ZodRawShape {
  return Object.fromEntries(
    columns.map((column) => [column.name, valueSchema(column).nullable().optional()])
  )
}

function filterSchema(columns: Column[]) {
  return z.object({
    column: z.enum(columnNames(columns)).describe('Column to filter on.'),
    operator: z.enum(FILTER_OPERATORS).describe(OPERATOR_GUIDE),
    value: z
      .string()
      .describe(
        'Value to compare against, as text. For in, pass a comma-separated list. For is, pass null, true, or false.'
      ),
  })
}

const selectSchema = z
  .string()
  .optional()
  .describe(
    'Columns to return, comma-separated. Defaults to every column. Related rows can be embedded, e.g. "id,title,author(name)".'
  )

const orderSchema = z
  .string()
  .optional()
  .describe('Sort order, e.g. "created_at.desc" or "priority.asc,created_at.desc".')

// -----------------------------------------------------------------------------
// Query translation
// -----------------------------------------------------------------------------

/** Format a filter value for the operators that need a specific shape. */
function filterValue({ operator, value }: Filter): string {
  if (operator === 'in') {
    const list = value.replace(/^\(|\)$/g, '')
    return `(${list})`
  }
  return value
}

// The query builder's own generics change shape as calls are chained, so these
// helpers ask only for the method they use and for it to return the builder.
type Filterable<T> = { filter(column: string, operator: string, value: unknown): T }
type Orderable<T> = { order(column: string, options: { ascending: boolean }): T }

function applyFilters<T extends Filterable<T>>(query: T, filters: Filter[] | undefined): T {
  let filtered = query
  for (const filter of filters ?? []) {
    filtered = filtered.filter(filter.column, filter.operator, filterValue(filter))
  }
  return filtered
}

function applyOrder<T extends Orderable<T>>(query: T, order: string | undefined): T {
  let ordered = query
  for (const term of (order ?? '').split(',')) {
    const [column, direction] = term.trim().split('.')
    if (!column) continue
    ordered = ordered.order(column, { ascending: direction !== 'desc' })
  }
  return ordered
}

// -----------------------------------------------------------------------------
// Tool registration
// -----------------------------------------------------------------------------

function registerResourceTools(
  server: McpServer,
  supabase: SupabaseClient,
  resource: Resource
): void {
  const filter = filterSchema(resource.columns)
  const summary = columnSummary(resource.columns)
  const context = resource.description ? ` ${resource.description}` : ''

  if (resource.canSelect) {
    server.registerTool(
      toolName('list', resource.name),
      {
        description:
          `Read rows from ${resource.name}.${context} Columns: ${summary}. ` +
          'Row Level Security decides which rows are visible.',
        inputSchema: {
          filters: z.array(filter).optional().describe('Conditions, combined with AND.'),
          select: selectSchema,
          order: orderSchema,
          limit: z
            .number()
            .int()
            .min(1)
            .max(MAX_ROWS)
            .optional()
            .describe(`Maximum rows to return. Defaults to ${DEFAULT_ROWS}.`),
          offset: z.number().int().min(0).optional().describe('Rows to skip, for paging.'),
        },
        annotations: { readOnlyHint: true, destructiveHint: false, openWorldHint: false },
      },
      async ({ filters, select, order, limit, offset }) => {
        try {
          const size = limit ?? DEFAULT_ROWS
          const from = offset ?? 0

          let query = supabase.from(resource.name).select(select ?? '*')
          query = applyFilters(query, filters as Filter[] | undefined)
          query = applyOrder(query, order)
          query = query.range(from, from + size - 1)

          const { data, error } = await query
          if (error) throw error
          return jsonResult(data)
        } catch (error) {
          return runtimeErrorResult(error)
        }
      }
    )
  }

  if (resource.canInsert) {
    server.registerTool(
      toolName('create', resource.name),
      {
        description: `Insert rows into ${resource.name}.${context} Returns the inserted rows.`,
        inputSchema: {
          rows: z
            .array(z.object(insertShape(resource.columns)))
            .min(1)
            .describe('Rows to insert.'),
          select: selectSchema,
        },
        annotations: { readOnlyHint: false, destructiveHint: false, openWorldHint: false },
      },
      async ({ rows, select }) => {
        try {
          const { data, error } = await supabase
            .from(resource.name)
            .insert(rows)
            .select(select ?? '*')
          if (error) throw error
          return jsonResult(data)
        } catch (error) {
          return runtimeErrorResult(error)
        }
      }
    )
  }

  if (resource.canUpdate) {
    server.registerTool(
      toolName('update', resource.name),
      {
        description:
          `Update rows in ${resource.name}.${context} Requires at least one filter, ` +
          'so an accidental call cannot rewrite the whole table. Returns the updated rows.',
        inputSchema: {
          // Required and non-empty: without a filter PostgREST would update
          // every row the caller can reach.
          filters: z
            .array(filter)
            .min(1)
            .describe('Conditions selecting the rows to update, combined with AND.'),
          values: z
            .object(updateShape(resource.columns))
            .describe('Columns to set. Pass null to clear a column.'),
          select: selectSchema,
        },
        annotations: {
          readOnlyHint: false,
          destructiveHint: false,
          idempotentHint: true,
          openWorldHint: false,
        },
      },
      async ({ filters, values, select }) => {
        try {
          let query = supabase.from(resource.name).update(values)
          query = applyFilters(query, filters as Filter[])
          const { data, error } = await query.select(select ?? '*')
          if (error) throw error
          return jsonResult(data)
        } catch (error) {
          return runtimeErrorResult(error)
        }
      }
    )
  }

  if (resource.canDelete) {
    server.registerTool(
      toolName('delete', resource.name),
      {
        description:
          `Delete rows from ${resource.name}.${context} Requires at least one filter, ` +
          'so an accidental call cannot empty the table. Returns the deleted rows.',
        inputSchema: {
          filters: z
            .array(filter)
            .min(1)
            .describe('Conditions selecting the rows to delete, combined with AND.'),
        },
        annotations: { readOnlyHint: false, destructiveHint: true, openWorldHint: false },
      },
      async ({ filters }) => {
        try {
          let query = supabase.from(resource.name).delete()
          query = applyFilters(query, filters as Filter[])
          const { data, error } = await query.select('*')
          if (error) throw error
          return jsonResult(data)
        } catch (error) {
          return runtimeErrorResult(error)
        }
      }
    )
  }
}

function registerFunctionTool(
  server: McpServer,
  supabase: SupabaseClient,
  rpcFunction: RpcFunction
): void {
  // Annotated, because the two branches would otherwise widen to a union that
  // does not satisfy the SDK's raw-shape parameter.
  const shape: z.ZodRawShape = rpcFunction.args.length
    ? { args: z.object(insertShape(rpcFunction.args)).describe('Function arguments.') }
    : {}

  server.registerTool(
    toolName('call', rpcFunction.name),
    {
      description:
        `Call the database function ${rpcFunction.name}.` +
        (rpcFunction.description ? ` ${rpcFunction.description}` : ''),
      inputSchema: shape,
      annotations: {
        readOnlyHint: rpcFunction.isReadOnly,
        destructiveHint: !rpcFunction.isReadOnly,
        openWorldHint: false,
      },
    },
    async (input: { args?: Record<string, unknown> }) => {
      try {
        const { data, error } = await supabase.rpc(rpcFunction.name, input.args ?? {})
        if (error) throw error
        return jsonResult(data)
      } catch (error) {
        return runtimeErrorResult(error)
      }
    }
  )
}

/** Register a tool set for every table, view, and function in the schema. */
export function registerSchemaTools(
  server: McpServer,
  supabase: SupabaseClient,
  schema: ApiSchema
): void {
  for (const resource of schema.resources) {
    registerResourceTools(server, supabase, resource)
  }
  for (const rpcFunction of schema.functions) {
    registerFunctionTool(server, supabase, rpcFunction)
  }
}

import { echoToolset } from './echo.ts'
import { postgrestToolset } from './postgrest/index.ts'
import { registerToolset } from './registry.ts'
import { whoamiToolset } from './whoami.ts'

export type { ToolContext } from './types.ts'

// The toolset manifest, replaced by this block to add the PostgREST toolset.
//
// shadcn copies whole files, so a block that adds tools ships its own version of
// this file: the framework's toolsets plus its own. If you install another
// toolset block later, or write your own, add its registerToolset call here.
//
// Called once at module scope, not per request.
export function registerToolsets(): void {
  registerToolset(echoToolset)
  registerToolset(whoamiToolset)
  registerToolset(postgrestToolset)
}
